import re


def title_of(html: str) -> str:
    """Text between the first `<title>` and the next `</title>` in html.

    Tags are matched case-insensitively and the text is returned exactly as
    written (no stripping, no entity decoding). Returns "" if there is no
    `<title>` tag, or if it is never closed. Works only on the given string;
    no network access.
    """
    m = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if m is None:
        return ""
    return m.group(1)


def test_basic() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_string() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Mixed</TiTlE></HTML>") == "Mixed"


def test_unclosed_title() -> None:
    assert title_of("<html><title>Oops<body>text</body></html>") == ""


def test_closing_tag_only() -> None:
    assert title_of("</title>") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced \n out </title>") == "  spaced \n out "


def test_text_with_special_characters() -> None:
    assert title_of("<title>A &amp; B | C</title>") == "A &amp; B | C"


def test_title_not_in_head() -> None:
    assert title_of("<body><p>x</p><title>Late</title></body>") == "Late"

